              "summary": "- AI 수요 폭발과 30% 이상의 공급 부족이 견인하는 역대급 실적 성장세- 1.6T·OCS·CPO 기술 선점 및 제조 효율화를 통한 가파른 영업마진 확장- 압도적 EPS 성장과 대규모 자금력을 바탕으로 한 밸류에이션 리레이팅 가시성",
              "pages": "4",
